dynamic-indexer:
  catalog-cdc:
    bootstrap-servers: ${KAFKA_CDC_CATALOG_SERVER}
    topic: ${KAFKA_CDC_CATALOG_TOPIC}
    group-id: ${KAFKA_CDC_CATALOG_GROUP_ID}
    concurrency: ${KAFKA_CDC_CATALOG_CONCURRENCY}
    properties:
      auto-offset-reset: ${KAFKA_CDC_CATALOG_PROP_AUTO_OFFSET_RESET}
      enable-auto-commit: ${KAFKA_CDC_CATALOG_PROP_ENABLE_AUTO_COMMIT}
      max-poll-records: ${KAFKA_CDC_CATALOG_PROP_MAX_POLL_RECORDS}
      fetch-max-wait-ms: ${KAFKA_CDC_CATALOG_PROP_FETCH_MAX_WAIT_MS}
      fetch-min-size: ${KAFKA_CDC_CATALOG_PROP_FETCH_MIN_SIZE}
      session-timeout-ms: ${KAFKA_CDC_CATALOG_PROP_SESSION_TIMEOUT_MS}
      schema-registry-url: ${KAFKA_CDC_CATALOG_PROP_SCHEMA_REGISTRY_URL}
      specific-avro-reader: ${KAFKA_CDC_CATALOG_PROP_SPECIFIC_AVRO_READER}
      heartbeat-interval-ms: ${KAFKA_CDC_CATALOG_PROP_HEARTBEAT_INTERVAL_MS}
      security-protocol: ${KAFKA_CDC_CATALOG_PROP_SECURITY_PROTOCOL}
      sasl-mechanism: ${KAFKA_CDC_CATALOG_PROP_SASL_MECHANISM}
      sasl-jaas-config: ${KAFKA_CDC_CATALOG_PROP_SASL_JAAS_CONFIG}

  product-cdc:
    bootstrap-servers: ${KAFKA_CDC_PRODUCT_SERVER}
    topic: ${KAFKA_CDC_PRODUCT_TOPIC}
    group-id: ${KAFKA_CDC_PRODUCT_GROUP_ID}
    concurrency: ${KAFKA_CDC_PRODUCT_CONCURRENCY}
    properties:
      auto-offset-reset: ${KAFKA_CDC_PRODUCT_PROP_AUTO_OFFSET_RESET}
      enable-auto-commit: ${KAFKA_CDC_PRODUCT_PROP_ENABLE_AUTO_COMMIT}
      max-poll-records: ${KAFKA_CDC_PRODUCT_PROP_MAX_POLL_RECORDS}
      fetch-max-wait-ms: ${KAFKA_CDC_PRODUCT_PROP_FETCH_MAX_WAIT_MS}
      fetch-min-size: ${KAFKA_CDC_PRODUCT_PROP_FETCH_MIN_SIZE}
      session-timeout-ms: ${KAFKA_CDC_PRODUCT_PROP_SESSION_TIMEOUT_MS}
      schema-registry-url: ${KAFKA_CDC_PRODUCT_PROP_SCHEMA_REGISTRY_URL}
      specific-avro-reader: ${KAFKA_CDC_PRODUCT_PROP_SPECIFIC_AVRO_READER}
      heartbeat-interval-ms: ${KAFKA_CDC_PRODUCT_PROP_HEARTBEAT_INTERVAL_MS}
      security-protocol: ${KAFKA_CDC_PRODUCT_PROP_SECURITY_PROTOCOL}
      sasl-mechanism: ${KAFKA_CDC_PRODUCT_PROP_SASL_MECHANISM}
      sasl-jaas-config: ${KAFKA_CDC_PRODUCT_PROP_SASL_JAAS_CONFIG}

  indexer-admin:
    bootstrap-servers: ${KAFKA_INDEXER_ADMIN_SERVER}
    topic: ${KAFKA_INDEXER_ADMIN_TOPIC}
    group-id: ${KAFKA_INDEXER_ADMIN_GROUP_ID}
    concurrency: ${KAFKA_INDEXER_ADMIN_CONCURRENCY}
    properties:
      auto-offset-reset: ${KAFKA_INDEXER_ADMIN_PROP_AUTO_OFFSET_RESET}
      enable-auto-commit: ${KAFKA_INDEXER_ADMIN_PROP_ENABLE_AUTO_COMMIT}
      security-protocol: ${KAFKA_INDEXER_ADMIN_PROP_SECURITY_PROTOCOL}
      sasl-mechanism: ${KAFKA_INDEXER_ADMIN_PROP_SASL_MECHANISM}
      sasl-jaas-config: ${KAFKA_INDEXER_ADMIN_PROP_SASL_JAAS_CONFIG}

elasticsearch:
    urls:
      - ${ELASTICSEARCH_URLS}
    api-key: ${ELASTICSEARCH_API_KEY}
    connection-timeout: ${ELASTICSEARCH_CONNECTION_TIMEOUT:5000}
    socket-timeout: ${ELASTICSEARCH_SOCKET_TIMEOUT:5000}

client:
  proxy-api:
    baseUrl: ${PROXY_API_BASEURL}
    username: ${PROXY_API_USERNAME}
    password: ${PROXY_API_PASSWORD}

valkey:
  backend:
    hosts: ${VALKEY_BACKEND_HOST}
    password: ${VALKEY_BACKEND_PASSWORD}
    database: ${VALKEY_BACKEND_DATABASE}

proxy:
  cache:
    l1:
      default-ttl-minutes: 30
      max-size: 10000
    l2:
      default-ttl-minutes: 60
    entity:
      category:
        key-prefix: platform-search.index.category.cache
      brand:
        key-prefix: platform-search.index.brand.cache
      manufacturer:
        key-prefix: platform-search.index.manufacturer.cache
      mall:
        key-prefix: platform-search.index.mall.cache

